{
  "state_id": "S002",
  "navigation_state": "Find MAIB investigation analysis or conclusions about a comparable surface-vessel encounter. Conditions are not supplied. Own ship is underway. The traffic situation is a ship at relative bearing 45.26442427598607 degrees, heading 270.0 degrees at 6.17 knots, rapidly closing, with projected CPA 27.4 metres and TCPA 681.0 seconds. The decision question is whether tactical intervention is required, while preserving predictable course and speed when collision risk is not established. The OOW proposal under review is alter_course with course change 60.0 degrees and target speed 0.0 knots. Prefer investigator findings over quoted regulations.",
  "candidate_cards": [
    {
      "annotation_id": "P001",
      "investigator_finding": "Misclassification caused target motion analysis to overestimate Karen's speed and range; the subsequent close pass should have triggered reassessment.",
      "transferable_lesson": "Keep classification-dependent motion estimates provisional, and re-evaluate the solution when observed proximity contradicts it rather than dismissing the contact and moving on.",
      "non_transfer_conditions": [
        "The specific speed-to-range error applies to the passive-sonar analysis described, not automatically to independently measured radar or visual ranges.",
        "The finding does not establish a numerical CPA or TCPA threshold."
      ],
      "supporting_quotations": [
        {
          "page": 12,
          "quote": "The misidentification of Karen as a merchant vessel also led directly to the TMA process over-estimating the fishing vessel’s speed and, therefore, its range"
        },
        {
          "page": 13,
          "quote": "This could have prompted them to re-evaluate the situation leading to an appreciation of a slower, closer contact."
        },
        {
          "page": 13,
          "quote": "the command team’s attention rapidly diverted to analysis of other sonar contacts."
        }
      ]
    },
    {
      "annotation_id": "P002",
      "investigator_finding": "Neither bridge team adopted the manoeuvring, lookout, steering and sound-signal preparations identified in the analysis.",
      "transferable_lesson": "Prepare propulsion, steering, lookout and sound signalling for restricted visibility before a close-quarters situation demands an immediate response; a schedule-driven speed adjustment is not a substitute for that preparation.",
      "non_transfer_conditions": [
        "These specific preparedness deficiencies should not be assumed where equivalent arrangements are already effective.",
        "The report does not establish a universal speed or steering setting."
      ],
      "supporting_quotations": [
        {
          "page": 10,
          "quote": "The master reduced speed, but only to arrive at the pilot station on time."
        },
        {
          "page": 10,
          "quote": "Neither vessel’s bridge teams reduced to manoeuvring speed, enhanced their ability to keep a lookout (either by eye or radar), transferred from autopilot to manual steering, or made the required sound signal."
        }
      ]
    },
    {
      "annotation_id": "P017",
      "investigator_finding": "At 25 knots the master had less than five minutes to assess and react, while stopping required more distance than remained to the yacht.",
      "transferable_lesson": "Evaluate speed against the time needed to assess uncertain contact information and the distance needed for effective response, not merely the current predicted CPA.",
      "non_transfer_conditions": [
        "The quoted times and stopping distance are specific to this ship and encounter, not universal speed limits or performance figures."
      ],
      "supporting_quotations": [
        {
          "page": 12,
          "quote": "At 25 knots, the master had less than 5 minutes to assess the situation and react to the yacht's unexpected action using potentially inaccurate data, and could only have stopped after 2.4 miles, which was beyond the yacht's position at the time."
        }
      ]
    },
    {
      "annotation_id": "P071",
      "investigator_finding": "Celtit's oblique traffic-lane crossing contravened the regulations, although the analysis acknowledged that temporary collision avoidance involving other vessels could mitigate that apparent contravention.",
      "transferable_lesson": "Check traffic-lane crossing compliance while considering the immediate collision-avoidance circumstances; do not assess crossing alignment in isolation from other contacts.",
      "non_transfer_conditions": [
        "This lesson concerns a traffic separation scheme, not an unrestricted open-water crossing.",
        "The report did not establish why Celtit changed to the oblique heading.",
        "It does not justify an arbitrary oblique crossing or prescribe a heading."
      ],
      "supporting_quotations": [
        {
          "page": 20,
          "quote": "Celtit was on a heading of about 175° crossing the traffic lane at an oblique angle in contravention of the Collision Regulations."
        },
        {
          "page": 18,
          "quote": "it is possible that she had altered from her intended track of about 150° temporarily to avoid collisions with two other vessels"
        },
        {
          "page": 18,
          "quote": "This would serve to mitigate the apparent contravention of Rule 10 (c)."
        }
      ]
    },
    {
      "annotation_id": "P073",
      "investigator_finding": "Union Arbo acted too late; the analysis emphasised that stand-on action timing must account for vessel limitations and surrounding circumstances.",
      "transferable_lesson": "Do not treat stand-on status as a reason to wait indefinitely. Decide when to intervene using observed non-action, relative manoeuvrability and size, nearby traffic, and navigational hazards, preserving sufficient room for effective action.",
      "non_transfer_conditions": [
        "This lesson does not assign stand-on status where roles are uncertain.",
        "The report supplies no universal range or time threshold; its larger, less manoeuvrable vessel reasoning must not be applied without considering actual vessel capabilities and constraints."
      ],
      "supporting_quotations": [
        {
          "page": 9,
          "quote": "The master of Union Arbo did not take appropriate action early enough to best avoid collision when it became apparent to him that Philomena was not taking appropriate action."
        },
        {
          "page": 6,
          "quote": "In other words, the larger or less manoeuvrable vessel is obliged to act earlier"
        },
        {
          "page": 6,
          "quote": "the watchkeeper should take into consideration the special circumstances of the situation, such as the differences in the manoeuvrability and size of vessels, nearby traffic and navigational hazards, and decide when he should take his/her own avoiding action."
        }
      ]
    },
    {
      "annotation_id": "P104",
      "investigator_finding": "The third officer did not promptly inspect available ARPA information and apparently did not appreciate how the closing speed limited the time available.",
      "transferable_lesson": "Review acquired-target motion and CPA information promptly, and use closing speed to judge the time available rather than relying on range alone.",
      "non_transfer_conditions": [
        "The quoted ranges, closing speed and time window are accident-specific, not universal action thresholds.",
        "Where track information is unreliable, acquisition alone does not validate its estimates."
      ],
      "supporting_quotations": [
        {
          "page": 18,
          "quote": "her failure to view the ARPA information for Washington Senator, regarding her course, speed and CPA as soon as it became available"
        },
        {
          "page": 18,
          "quote": "the 36 knot closing speed of the two vessels, which gave less than 13 minutes in which to take avoiding action"
        }
      ]
    },
    {
      "annotation_id": "P137",
      "investigator_finding": "The investigator retained, as a possibility rather than an established sequence, that the ship had been crossing ahead and then altered towards the yacht at the last minute.",
      "transferable_lesson": "Keep an apparent crossing-ahead assessment under review for subsequent changes in the other vessel's motion.",
      "non_transfer_conditions": [
        "This possible sequence must not be treated as proof that the ship altered course.",
        "It does not establish that a safely crossing vessel in another encounter will turn towards own vessel."
      ],
      "supporting_quotations": [
        {
          "page": 10,
          "quote": "The possibility that the ship was, in fact, crossing ahead and altered course towards Bluebell of Warsash at the last minute, possibly in an attempt to avoid a collision with the yacht."
        }
      ]
    }
  ]
}

